#!/usr/bin/env bash
# GRUP_FIX + KOKPİT REDESIGN — TEDARİKÇİ/phantom hariç müşteri overdue + yeni sabit-ızgara kokpit.html.
set -e
cd /opt/krb-assessment
set -a; [ -f .env ] && . ./.env; set +a
PW="${POSTGRES_PASSWORD:-}"
KOKF=shells/kokpit.html
[ -f "$KOKF" ] || { echo "HATA: kokpit.html yok"; exit 1; }
cp server_container.mjs server_container.mjs.bak.$(date +%s)
cp "$KOKF" "$KOKF.bak.$(date +%s)"

echo "== 1) server GRUP fix =="
printf '%s' '' | base64 -d > fix_grup.py
python3 fix_grup.py
node --check server_container.mjs && echo SERVER_OK

echo "== 2) kokpit.html redesign (tam değiştir) =="
printf '%s' '' | base64 -d > "$KOKF"
echo "kokpit.html satır: $(wc -l < "$KOKF")"

echo "== 3) bugünkü içgörüyü sil (grup-düzeltilmiş yeniden üret) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -c "DELETE FROM bi_finansal_icgoru WHERE gun=CURRENT_DATE;"

docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
echo "== 110sn bekle =="; sleep 110

echo "== DÜZELTİLMİŞ KÖPRÜ (müşteri, tedarikçi HARİÇ) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -c \
 "SELECT round((baglam->'etki'->>'overdue_brut')::numeric/1e6,1) musteri_brut_M, round((baglam->'etki'->>'overdue')::numeric/1e6,1) net_M, round((baglam->'etki'->>'mahsup')::numeric/1e6,1) mahsup_M, round((baglam->'etki'->>'finans_maliyeti_yil')::numeric/1e6,1) finans_yil_M, (baglam->'etki'->>'finans_pct_brutkar') pct_brutkar FROM bi_finansal_icgoru WHERE gun=CURRENT_DATE;"
echo "== EN BÜYÜK NET GECİKMİŞ MÜŞTERİLER (TEVZİ olMAMALI) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -F $'\t' -A <<'SQL'
SELECT left(t->>'ad',30) musteri, round((t->>'overdue')::numeric/1e6,1) net_M, round((t->>'brut')::numeric/1e6,1) brut_M
FROM bi_finansal_icgoru, jsonb_array_elements(baglam->'koken'->'top') t WHERE gun=CURRENT_DATE LIMIT 8;
SQL
echo "== içgörü başlıkları =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -F $'\t' -A <<'SQL'
SELECT left(e->>'baslik',54) baslik FROM bi_finansal_icgoru, jsonb_array_elements(icgoruler) e WHERE gun=CURRENT_DATE;
SQL
echo "== DONE =="
